// Year 3 history to greater depth: the Stone Age to the Iron Age, the Roman army, Boudica,
// Roman life, Anglo-Saxons and Scots, the Vikings, Ancient Greece, the earliest civilisations,
// castles and sieges, the Battle of Britain and the Home Front (told gently), and historical
// skills; the Normans and Shang China as stretch. The last deck carries the one timeline for
// the course: the Year 2 timeline merged with the Year 3 events.

import KS1_HISTORY from '../ks1/history.mjs';

const fact = (id, topic, prompt, answer, distractors, explain, extra = {}) => ({ id: `history.${id}`, topic: `history.${topic}`, kind: 'fact', prompt, answer, distractors, explain, ...extra });
const mcq = (id, topic, prompt, options, explain, extra = {}) => ({ id: `history.${id}`, topic: `history.${topic}`, kind: 'mcq', prompt, options: options.map(([text, correct, feedback]) => ({ text, correct: !!correct, feedback })), explain, ...extra });
const order = (id, topic, prompt, items, explain, labels = null) => ({ id: `history.${id}`, topic: `history.${topic}`, kind: 'order', prompt, items, labels, explain });
const C = { formats: ['choice'] };

const topics = [
  { id: 'history.y3-stoneage', title: 'The Stone Age and Bronze Age', kind: 'facts', prereqs: ['history.stoneage'], batch: 5, intro: 'The Stone Age lasted for hundreds of thousands of years. People went from hunting mammoths with flint spears to farming, building villages like Skara Brae and raising Stonehenge. Then they learned to make bronze.', teach: 'Explain the difference between the Old Stone Age and the New Stone Age.', talk: 'Ask {him} what {she} would miss most if {she} lived in the Stone Age.' },
  { id: 'history.y3-ironage', title: 'The Iron Age and the Celts', kind: 'facts', prereqs: ['history.y3-stoneage'], batch: 5, intro: 'From about 800 BC, people in Britain learned to make iron, which is harder than bronze. Iron Age tribes built hill forts, drove chariots and followed priests called druids.', teach: 'Explain why a hill fort was a good place to defend.', talk: 'Ask {him} to design an Iron Age hill fort with ditches and a gate.' },
  { id: 'history.y3-legion', title: 'Inside the Roman army', kind: 'facts', prereqs: ['history.romans'], batch: 5, intro: 'The Roman army was one of the best-trained armies in history. Soldiers called legionaries trained every day, marched in step and fought as a team.', teach: 'Explain what a legionary carried and what each thing was for.', talk: 'Ask {him} which would be harder: marching 20 miles in armour, or building a fort at the end of it.' },
  { id: 'history.y3-boudica', title: 'Boudica, the warrior queen', kind: 'facts', prereqs: ['history.y3-legion'], batch: 5, intro: 'In about AD 60 or 61, Boudica, queen of the Iceni tribe, led a huge rebellion against the Romans. Her army destroyed three Roman towns before the Romans finally defeated her.', teach: 'Explain why Boudica rebelled against the Romans.', talk: 'Ask {him} whether {she} thinks Boudica was a hero, and why.' },
  { id: 'history.y3-roman-life', title: 'Roman life and what the Romans left us', kind: 'facts', prereqs: ['history.y3-legion'], batch: 5, intro: 'The Romans ruled Britain for nearly 400 years. They built towns, villas, baths and straight roads, and left behind words, numbers and even letters written on wood.', teach: 'Explain three things the Romans left behind that we still use.', talk: 'Look for a Roman road, a Roman numeral or a Latin word together this week.' },
  { id: 'history.y3-saxons', title: 'Anglo-Saxons and Scots', kind: 'facts', prereqs: ['history.y3-roman-life'], batch: 5, intro: 'After the Romans left, Angles, Saxons and Jutes sailed over from northern Europe and set up kingdoms. In the north, the Scots and Picts lived. England gets its name from the Angles!', teach: 'Explain what was found at Sutton Hoo and why it matters.', talk: 'Ask {him} which day of the week is named after an Anglo-Saxon god.' },
  { id: 'history.y3-vikings', title: 'Vikings and Anglo-Saxons: the struggle for England', kind: 'facts', prereqs: ['history.vikings', 'history.y3-saxons'], batch: 5, intro: 'For about 250 years, Vikings and Anglo-Saxons raided, fought, made peace and traded. In the end, England became one kingdom.', teach: 'Explain how Alfred the Great defended Wessex from the Vikings.', talk: 'Ask {him} to write {her} name in Viking runes (find a rune alphabet in a library book).' },
  { id: 'history.y3-greece', title: 'Ancient Greece', kind: 'facts', prereqs: ['history.past'], batch: 5, intro: 'About 2,500 years ago, the cities of Ancient Greece gave the world the Olympic Games, democracy, theatre and many great thinkers. Athens and Sparta were very different cities.', teach: 'Explain the difference between Athens and Sparta.', talk: 'Ask {him} which Greek god or goddess {she} would like to be, and why.' },
  { id: 'history.y3-civilisations', title: 'The first great civilisations', kind: 'facts', prereqs: ['history.egypt'], batch: 5, intro: 'More than 4,000 years ago, the first great civilisations grew up beside rivers: in Sumer, in the Indus Valley and in Egypt. They built cities and invented writing.', teach: 'Explain why the first cities were built beside rivers.', talk: 'Ask {him} what {she} would need to build a city from nothing.' },
  { id: 'history.y3-sieges', title: 'Castles under attack', kind: 'facts', prereqs: ['history.castles'], batch: 5, intro: 'Attacking a castle was very hard. Attackers used giant catapults, siege towers, battering rams and tunnels, and defenders kept making castles stronger.', teach: 'Explain why a concentric castle was so hard to attack.', talk: 'Build a castle from cushions or blocks and ask {him} how {she} would defend it.' },
  { id: 'history.y3-britain1940', title: 'The Battle of Britain', kind: 'facts', prereqs: ['history.ww2'], batch: 5, intro: 'In the summer of 1940, the German air force tried to defeat Britain’s Royal Air Force. Radar, brave pilots from many countries and a clever control system helped Britain hold on.', teach: 'Explain how radar helped the RAF.', talk: 'Ask {him} why Churchill called the pilots “the Few”.' },
  { id: 'history.y3-homefront', title: 'The Home Front', kind: 'facts', prereqs: ['history.y3-britain1940'], batch: 5, intro: 'During the Second World War, ordinary people helped too: they kept the blackout, grew vegetables, worked on farms and in factories, and sheltered from air raids.', teach: 'Explain how families kept safe during an air raid.', talk: 'Ask an older relative if their family had an Anderson shelter or grew vegetables for victory.' },
  { id: 'history.y3-skills', title: 'Thinking like a historian', kind: 'facts', prereqs: ['history.past'], batch: 5, intro: 'Historians use dates, put events in order, and look at evidence from the past. Some evidence was made at the time; some was made much later.', teach: 'Explain the difference between a primary source and a secondary source.', talk: 'Find something old at home (a photo, a coin) and ask {him} what it tells you about the past.' },
  // stretch
  { id: 'history.y3-normans', title: 'The Normans in charge', kind: 'facts', tier: 'stretch', prereqs: ['history.1066', 'history.y3-sieges'], batch: 5, intro: 'After 1066, William the Conqueror and the Normans took control of England. They built castles everywhere, counted everything in the Domesday Book, and set up the feudal system.', teach: 'Explain how the feudal system worked, from the king down to the peasants.', talk: 'Ask {him} what the Domesday Book might have said about your town.' },
  { id: 'history.y3-shang', title: 'Shang China', kind: 'facts', tier: 'stretch', prereqs: ['history.y3-civilisations'], batch: 5, intro: 'About 3,500 years ago, the Shang dynasty ruled part of China beside the Yellow River. They made beautiful bronze and wrote questions to their ancestors on bones.', teach: 'Explain what oracle bones were.', talk: 'Ask {him} what question {she} would write on an oracle bone.' },
];

const items = [
  // --- Stone Age and Bronze Age
  order('y3.sa.periods', 'y3-stoneage', 'Put the three parts of the Stone Age in order, earliest first.', ['Palaeolithic (Old Stone Age)', 'Mesolithic (Middle Stone Age)', 'Neolithic (New Stone Age)'], 'Palaeo means old, meso means middle and neo means new. “Lithic” means stone.'),
  mcq('y3.sa.neolithic', 'y3-stoneage', 'What big change happened in the Neolithic (New Stone Age)?', [['People began farming and living in villages', true], ['People began driving carts with engines', false, 'Engines came thousands of years later.'], ['People first used iron', false, 'Iron came much later, in the Iron Age.']], 'Farming reached Britain about 6,000 years ago. People settled down to grow crops and keep animals.'),
  fact('y3.sa.hunter', 'y3-stoneage', 'Early Stone Age people moved around to hunt animals and collect plants. What are they called?', 'hunter-gatherers', ['farmers', 'knights', 'merchants'], 'They hunted animals and gathered berries, nuts and roots.', C),
  fact('y3.sa.skara', 'y3-stoneage', 'Which Stone Age village in Orkney was uncovered by a great storm in 1850?', 'Skara Brae', ['Stonehenge', 'Jorvik', 'Sutton Hoo'], 'A storm blew the sand away and revealed stone houses about 5,000 years old, with stone beds and dressers.', { accept: ['skara brae'] }),
  fact('y3.sa.bluestones', 'y3-stoneage', 'Some of the smaller stones at Stonehenge, the bluestones, came from far away. Where from?', 'the Preseli Hills in Wales', ['the mountains of Scotland', 'the Alps in Switzerland', 'a quarry in London'], 'They were moved about 150 miles, probably by people pulling them on sledges and rollers.', C),
  fact('y3.sa.cheddar', 'y3-stoneage', 'Cheddar Man is Britain’s oldest almost complete skeleton. About how long ago did he live?', 'about 10,000 years ago', ['about 100 years ago', 'about 1,000 years ago', 'about a million years ago'], 'He was found in Gough’s Cave in Cheddar Gorge, Somerset, in 1903. He lived in the Middle Stone Age.', C),
  fact('y3.sa.amesbury', 'y3-stoneage', 'A rich grave found near Stonehenge in 2002 belonged to a man buried about 4,300 years ago with arrowheads, copper knives and gold. What do we call him?', 'the Amesbury Archer', ['the Iceni King', 'Cheddar Man', 'the Lindow Man'], 'Tests on his teeth show he grew up in the Alps area of central Europe, so he had travelled a very long way.', C),
  mcq('y3.sa.bronze', 'y3-stoneage', 'Bronze is made by mixing which two metals?', [['copper and tin', true], ['gold and silver', false, 'Gold and silver were used for jewellery. Bronze is copper and tin.'], ['iron and steel', false, 'Steel is made from iron. Bronze is copper and tin.']], 'Tin was mined in Cornwall. Bronze tools and weapons were harder than copper ones.'),
  fact('y3.sa.flint', 'y3-stoneage', 'At Grimes Graves in Norfolk, Stone Age people dug deep mines to find which stone for tools?', 'flint', ['coal', 'gold', 'chalk'], 'Flint can be chipped into a very sharp edge for axes and arrowheads.'),
  mcq('y3.sa.evidence', 'y3-stoneage', 'Stone Age people did not write. How do we know about them?', [['From the things they left behind', true], ['From the diaries they kept', false, 'There was no writing in Stone Age Britain.'], ['From very old photographs', false, 'Cameras were invented less than 200 years ago.']], 'Archaeologists study objects and remains to work out how people lived.'),

  // --- Iron Age and Celts
  fact('y3.ia.when', 'y3-ironage', 'About when did the Iron Age begin in Britain?', 'about 800 BC', ['about AD 800', 'about 1800', 'about 10,000 BC'], 'It lasted until the Romans arrived in AD 43.', C),
  mcq('y3.ia.better', 'y3-ironage', 'Why was iron better than bronze for tools and weapons?', [['Iron is harder', true], ['Iron is much shinier', false, 'Bronze is actually shinier. Iron was harder and easier to find.'], ['Iron never goes rusty', false, 'Iron does rust!']], 'Iron ore was found in lots of places, so more people could have strong tools.'),
  fact('y3.ia.maiden', 'y3-ironage', 'Which huge Iron Age hill fort in Dorset has enormous banks and ditches?', 'Maiden Castle', ['Hadrian’s Wall', 'the Tower of London', 'Skara Brae'], 'It is one of the largest hill forts in Europe. It was not a castle with stone walls, but earth banks.', C),
  mcq('y3.ia.hillfort', 'y3-ironage', 'Why did Iron Age people build forts on hilltops?', [['They could see enemies coming', true], ['It was warmer at the top', false, 'Hills are usually colder and windier!'], ['There was more water up high', false, 'Water was usually easier to find lower down.']], 'Ditches and banks around the top made attackers climb uphill.'),
  fact('y3.ia.druids', 'y3-ironage', 'What were Celtic priests and wise people called?', 'druids', ['monks', 'centurions', 'pharaohs'], 'Druids led ceremonies and were also judges and teachers.', { accept: ['druid'] }),
  fact('y3.ia.chariot', 'y3-ironage', 'Iron Age warriors rode into battle on a light, two-wheeled cart pulled by ponies. What was it called?', 'a chariot', ['a carriage', 'a longship', 'a tank'], 'Julius Caesar wrote about how skilfully British warriors drove their chariots.', { accept: ['chariot'] }),
  fact('y3.ia.torc', 'y3-ironage', 'What was a torc?', 'a metal neck ring', ['a type of short sword', 'a kind of round house', 'a loud war cry'], 'The Great Torc from Snettisham in Norfolk is made of gold and is in the British Museum.', C),
  mcq('y3.ia.coins', 'y3-ironage', 'What did some Iron Age tribes make for the first time in Britain, near the end of the Iron Age?', [['their own coins', true], ['paper books', false, 'Books came much later.'], ['bicycles', false, 'Bicycles were invented in the 1800s.']], 'Some coins show the names of tribal leaders, which helps historians.'),
  fact('y3.ia.roundhouse', 'y3-ironage', 'Where was the fire in an Iron Age roundhouse?', 'in the middle', ['outside the door', 'on the roof', 'there was no fire'], 'The smoke drifted up through the thatched roof. Families cooked, ate and slept around it.', C),
  mcq('y3.ia.tribes', 'y3-ironage', 'Iron Age Britain was not one country. How was it organised?', [['Into many tribes', true], ['Ruled by one king in London', false, 'There was no London yet! The Romans founded it.'], ['Ruled by the Romans from Rome', false, 'The Romans came at the END of the Iron Age.']], 'Tribes included the Iceni, the Brigantes and the Catuvellauni.'),

  // --- Roman army
  fact('y3.leg.caesar', 'y3-legion', 'Which famous Roman general visited Britain with his army in 55 and 54 BC, but did not stay?', 'Julius Caesar', ['Claudius', 'Hadrian', 'Boudica'], 'Caesar won some battles but went back to Gaul (France). The real invasion came almost 100 years later.', { accept: ['caesar'] }),
  fact('y3.leg.claudius', 'y3-legion', 'Which Roman emperor sent the army that invaded Britain in AD 43?', 'Claudius', ['Julius Caesar', 'Nero', 'Hadrian'], 'Claudius even came to Britain himself, and is said to have brought elephants!', { accept: ['emperor claudius'] }),
  fact('y3.leg.legionary', 'y3-legion', 'What was an ordinary Roman foot soldier called?', 'a legionary', ['a centurion', 'a gladiator', 'a druid'], 'Legionaries had to be Roman citizens and served for about 25 years.', { accept: ['legionary', 'legionnaire'] }),
  fact('y3.leg.centurion', 'y3-legion', 'Who commanded a group of about 80 legionaries?', 'a centurion', ['an emperor', 'a senator', 'a squire'], 'The name comes from the Latin for a hundred, though a century usually had 80 men.', { accept: ['centurion'] }),
  mcq('y3.leg.kit', 'y3-legion', 'Which of these did a legionary NOT carry?', [['a longbow', true], ['a short sword (gladius)', false, 'The gladius was his main weapon.'], ['a curved shield (scutum)', false, 'The scutum protected him and his friends.'], ['a throwing spear (pilum)', false, 'He threw his pilum before the armies met.']], 'Longbows were used by English archers more than a thousand years later.'),
  mcq('y3.leg.testudo', 'y3-legion', 'In the “testudo” (tortoise) formation, how did soldiers use their shields?', [['They locked them into a shell', true], ['They threw them at the enemy', false, 'Shields were for protection.'], ['They used them as little boats', false, 'Not in battle!']], 'The shell of shields protected them from arrows and stones as they moved forward.'),
  mcq('y3.leg.camp', 'y3-legion', 'At the end of a long day’s march, what did Roman soldiers build?', [['A camp with a ditch and a fence', true], ['A tall castle made of stone', false, 'Stone castles came much later. They built a quick camp every night.'], ['Nothing: they slept anywhere', false, 'They always protected their camp.']], 'Every soldier carried tools for digging, so they could build a safe camp in a few hours.'),
  fact('y3.leg.caratacus', 'y3-legion', 'Which British leader fought the Romans for years, was captured, and was spared by Emperor Claudius after a brave speech in Rome?', 'Caratacus', ['Boudica', 'Alfred', 'Arthur'], 'He was handed over to the Romans in AD 51. Claudius was so impressed by his speech that he let him live.', C),
  fact('y3.leg.auxiliary', 'y3-legion', 'Soldiers in the Roman army who were not Roman citizens were called…', 'auxiliaries', ['legionaries', 'senators', 'gladiators'], 'Auxiliaries came from all over the empire. After 25 years they could become citizens.', C),
  fact('y3.leg.caligae', 'y3-legion', 'Roman soldiers wore tough leather sandals with iron nails in the soles. What were they called?', 'caligae', ['trainers', 'wellies', 'togas'], 'The nails gave grip, a bit like football boots.', C),

  // --- Boudica
  fact('y3.bo.tribe', 'y3-boudica', 'Boudica was queen of which tribe?', 'the Iceni', ['the Brigantes', 'the Romans', 'the Saxons'], 'The Iceni lived in what is now Norfolk and Suffolk.', { accept: ['iceni'] }),
  mcq('y3.bo.why', 'y3-boudica', 'Why did Boudica rebel?', [['The Romans took her tribe’s land', true], ['She wanted to become a Roman', false, 'She was fighting AGAINST Roman rule.'], ['The Romans stole her best chariot', false, 'It was much more serious: they took the tribe’s lands and treated her family cruelly.']], 'Her husband, King Prasutagus, had wanted to share his kingdom with the emperor. Instead, the Romans took everything.'),
  mcq('y3.bo.towns', 'y3-boudica', 'Which three Roman towns did Boudica’s army destroy?', [['Colchester, London and St Albans', true], ['York, Bath and Chester', false, 'Those were Roman towns, but not the ones Boudica attacked.'], ['Rome, Paris and Madrid', false, 'She fought in Britain.']], 'In Roman times they were called Camulodunum, Londinium and Verulamium.'),
  fact('y3.bo.when', 'y3-boudica', 'About when was Boudica’s revolt?', 'AD 60 or 61', ['AD 43', '1066', '55 BC'], 'Historians are not sure which of the two years it was.', C),
  mcq('y3.bo.end', 'y3-boudica', 'How did the revolt end?', [['A smaller Roman army beat her', true], ['Boudica became Emperor of Rome', false, 'She was defeated.'], ['The Romans left Britain for ever', false, 'They stayed for another 350 years.']], 'The Roman governor, Suetonius Paulinus, chose a narrow battlefield where the Romans’ training mattered most.'),
  mcq('y3.bo.tacitus', 'y3-boudica', 'Most of what we know about Boudica comes from Roman writers like Tacitus. Why should we be careful with their stories?', [['They were on the Roman side', true], ['Romans did not know how to write', false, 'Romans wrote a lot! The problem is whose side they were on.'], ['They were written in English', false, 'They wrote in Latin.']], 'The Iceni left no written records, so we only hear the Roman side.'),
  fact('y3.bo.statue', 'y3-boudica', 'A famous statue of Boudica stands near the Houses of Parliament in London. What is she riding?', 'a chariot', ['a horse', 'an elephant', 'a ship'], 'The bronze statue was put up in 1902.', { accept: ['chariot'] }),
  fact('y3.bo.governor', 'y3-boudica', 'Where was the Roman governor when Boudica’s revolt began?', 'attacking the island of Anglesey', ['back in Rome', 'on holiday in Spain', 'guarding London'], 'He was attacking the druids on Anglesey. He hurried back with his army, but could not save London.', C),

  // --- Roman life
  fact('y3.rl.wall', 'y3-roman-life', 'In about AD 122, which emperor ordered a great wall to be built across the north of England?', 'Hadrian', ['Claudius', 'Nero', 'Augustus'], 'Hadrian’s Wall ran about 73 miles from coast to coast.', { accept: ['emperor hadrian'] }),
  mcq('y3.rl.vindolanda', 'y3-roman-life', 'What are the Vindolanda tablets, found near Hadrian’s Wall?', [['Wooden letters written by Romans', true], ['Little pills of Roman medicine', false, 'They are writing tablets, not medicine.'], ['Stone tablets with laws on them', false, 'They are thin slices of wood with ink writing.']], 'One is a birthday party invitation from a lady called Claudia Severa. Another mentions socks and underpants sent to a soldier!'),
  fact('y3.rl.hypocaust', 'y3-roman-life', 'What was a hypocaust?', 'underfloor heating', ['a Roman toilet', 'a type of shield', 'a chariot race'], 'Hot air from a fire flowed under the floor, which rested on little pillars of tiles.', C),
  fact('y3.rl.bath', 'y3-roman-life', 'Which English city is named after the Roman baths built around its hot springs?', 'Bath', ['York', 'Chester', 'Colchester'], 'The Romans called it Aquae Sulis. You can still see the Great Bath today.', { accept: ['bath'] }),
  fact('y3.rl.fishbourne', 'y3-roman-life', 'Which huge Roman palace in West Sussex has amazing mosaic floors?', 'Fishbourne', ['Buckingham Palace', 'Hampton Court', 'Skara Brae'], 'A mosaic is a picture made from thousands of tiny coloured tiles.', C),
  mcq('y3.rl.roads', 'y3-roman-life', 'Why did the Romans build long, straight roads?', [['So soldiers and supplies could travel quickly', true], ['Because they did not know how to make bends', false, 'They could make bends, but straight was quickest.'], ['For chariot races', false, 'Races were held in arenas.']], 'A straight road is the shortest route. Watling Street and the Fosse Way are famous Roman roads.'),
  mcq('y3.rl.july', 'y3-roman-life', 'Which month is named after Julius Caesar?', [['July', true], ['June', false, 'June is named after the goddess Juno.'], ['January', false, 'January is named after the god Janus.']], 'And August is named after the Emperor Augustus.'),
  fact('y3.rl.london', 'y3-roman-life', 'Which great city was founded by the Romans and called Londinium?', 'London', ['Paris', 'Edinburgh', 'Dublin'], 'The Romans built a bridge over the Thames, and a town grew up beside it.', { accept: ['london'] }),
  fact('y3.rl.leave', 'y3-roman-life', 'About when did the Roman army leave Britain?', 'about AD 410', ['about AD 43', '1066', 'about 55 BC'], 'Rome itself was under attack, so the soldiers were needed at home.', C),
  mcq('y3.rl.latin', 'y3-roman-life', 'Which of these do we still use from the Romans?', [['Roman numerals and many words from Latin', true], ['Their gods for the days of the week', false, 'Most of our day names come from Anglo-Saxon gods.'], ['Their money', false, 'We use pounds and pence now.']], 'Words like “aquarium” (aqua = water) and “century” (centum = a hundred) come from Latin.'),

  // --- Anglo-Saxons and Scots
  mcq('y3.sx.where', 'y3-saxons', 'Where did the Angles, Saxons and Jutes come from?', [['Northern Europe, near Denmark', true], ['Italy, near the city of Rome', false, 'That is where the Romans came from.'], ['America, across the ocean', false, 'Nobody in Europe knew about America then.']], 'They began to arrive from about AD 450, after the Romans left.'),
  fact('y3.sx.england', 'y3-saxons', 'The word “England” comes from “Angle-land”. Which people is it named after?', 'the Angles', ['the Romans', 'the Vikings', 'the Normans'], 'Angle-land became England.', { accept: ['angles'] }),
  mcq('y3.sx.kingdoms', 'y3-saxons', 'Which of these was an Anglo-Saxon kingdom?', [['Wessex', true], ['Wakanda', false, 'That is from a film!'], ['Rome', false, 'Rome was in Italy.']], 'The big kingdoms included Wessex, Mercia, Northumbria, East Anglia and Kent.'),
  fact('y3.sx.suttonhoo', 'y3-saxons', 'In 1939, a buried ship full of treasure, including a famous helmet, was found in Suffolk. Where?', 'Sutton Hoo', ['Skara Brae', 'Stonehenge', 'Lindisfarne'], 'It was probably the grave of King Rædwald of East Anglia, who died about AD 624. The helmet is in the British Museum.', { accept: ['sutton hoo'] }),
  fact('y3.sx.augustine', 'y3-saxons', 'In AD 597, a monk was sent from Rome to Kent to spread Christianity. Who was he?', 'Augustine', ['Bede', 'Alfred', 'Offa'], 'He became the first Archbishop of Canterbury.', { accept: ['st augustine', 'saint augustine'] }),
  fact('y3.sx.bede', 'y3-saxons', 'Which Anglo-Saxon monk at Jarrow wrote a famous history of the English people?', 'Bede', ['Augustine', 'Beowulf', 'Cnut'], 'Bede finished his history in AD 731. He helped make AD dates popular.', { accept: ['the venerable bede', 'venerable bede'] }),
  fact('y3.sx.offa', 'y3-saxons', 'Which king of Mercia built a giant earth bank along the border with Wales?', 'Offa', ['Alfred', 'Arthur', 'Athelstan'], 'Offa’s Dyke is still there, and you can walk along it.', { accept: ['king offa'] }),
  mcq('y3.sx.days', 'y3-saxons', 'Which day of the week is named after the Anglo-Saxon god Woden?', [['Wednesday', true], ['Thursday', false, 'Thursday is named after Thunor (Thor), the thunder god.'], ['Friday', false, 'Friday is named after the goddess Frigg.']], 'Woden’s day became Wednesday. That is why there is a silent d in it!'),
  mcq('y3.sx.village', 'y3-saxons', 'What were most Anglo-Saxon houses made of?', [['Wood, with thatched roofs', true], ['Stone and glass', false, 'Most Anglo-Saxons built with wood.'], ['Bricks and concrete', false, 'That is modern!']], 'The most important building in a village was the lord’s great hall, where feasts were held.'),
  mcq('y3.sx.scots', 'y3-saxons', 'In early Scotland, which two peoples were later joined together under one king?', [['The Scots and the Picts', true], ['The Romans and the Greeks', false, 'They were never in Scotland together like that.'], ['The Iceni and the Vikings', false, 'The Iceni lived in the east of England.']], 'The Scots came over from Ireland; the Picts lived in the north and east. They were united in about AD 843.'),

  // --- Vikings in depth
  fact('y3.vk.lindisfarne', 'y3-vikings', 'In AD 793, Vikings attacked a famous monastery on a holy island off the coast of Northumberland. What was it called?', 'Lindisfarne', ['Iona', 'Jarrow', 'Canterbury'], 'This raid shocked everyone and is often seen as the start of the Viking Age in Britain.', { accept: ['holy island'] }),
  fact('y3.vk.edington', 'y3-vikings', 'In 878, Alfred the Great defeated the Viking leader Guthrum at which battle?', 'the Battle of Edington', ['the Battle of Hastings', 'the Battle of Britain', 'the Battle of Bosworth'], 'Afterwards Guthrum agreed to become a Christian, and England was divided between them.', C),
  mcq('y3.vk.danelaw', 'y3-vikings', 'What was the Danelaw?', [['The part of England ruled by Vikings', true], ['A law against Danish pastries', false, 'Ha! It was land ruled by the Danes (Vikings).'], ['A famous Viking longship', false, 'It was an area of land.']], 'After Edington, the north and east of England became the Danelaw. Alfred kept Wessex.'),
  mcq('y3.vk.burhs', 'y3-vikings', 'How did Alfred protect Wessex from more Viking attacks?', [['He built walled towns called burhs', true], ['He moved everyone to France', false, 'He stayed and defended Wessex.'], ['He gave the Vikings all his gold each year', false, 'He built defences instead.']], 'If the Vikings attacked, people could reach a burh quickly. Many burhs became towns we know today.'),
  mcq('y3.vk.cakes', 'y3-vikings', 'There is a famous legend about Alfred hiding from the Vikings. What did he do?', [['He let some cakes burn', true], ['He dressed up as a Viking', false, 'That is not the famous legend.'], ['He hid inside a whale', false, 'No whales in this story!']], 'It is a legend, so we cannot be sure it happened, but it shows how hard times were for Alfred.'),
  fact('y3.vk.athelstan', 'y3-vikings', 'Who became the first king of all England, in 927?', 'Athelstan', ['Alfred', 'Cnut', 'William'], 'Athelstan was Alfred’s grandson.', { accept: ['aethelstan', 'æthelstan'] }),
  fact('y3.vk.jorvik', 'y3-vikings', 'The Vikings called the city of York…', 'Jorvik', ['Londinium', 'Camulodunum', 'Valhalla'], 'Jorvik was a busy trading town. Archaeologists found Viking houses, shoes and even poo there!', { accept: ['jorvík'] }),
  fact('y3.vk.runes', 'y3-vikings', 'What were the letters of the Viking alphabet called?', 'runes', ['hieroglyphs', 'numerals', 'emojis'], 'Runes were made of straight lines, which are easy to carve into wood and stone.', { accept: ['rune'] }),
  mcq('y3.vk.thor', 'y3-vikings', 'Which Viking god carried a mighty hammer?', [['Thor', true], ['Odin', false, 'Odin was the chief god, with one eye and two ravens.'], ['Loki', false, 'Loki was the trickster god.']], 'Viking warriors hoped to go to Valhalla, Odin’s great hall, when they died.'),
  fact('y3.vk.cnut', 'y3-vikings', 'Which Viking king ruled England from 1016, and also Denmark and Norway?', 'Cnut', ['Alfred', 'Harold', 'Offa'], 'A famous story says he sat on the beach and showed that even a king cannot stop the tide.', { accept: ['canute', 'king cnut', 'knut'] }),

  // --- Ancient Greece
  fact('y3.gr.olympics', 'y3-greece', 'In which year did the first recorded Olympic Games take place, in Olympia?', '776 BC', ['AD 776', '1066', 'AD 2012'], 'The games honoured Zeus. Only men could compete, and winners got a crown of olive leaves.', C),
  mcq('y3.gr.democracy', 'y3-greece', 'Athens is famous for inventing democracy. What does democracy mean?', [['Rule by the people', true], ['Rule by one king or queen', false, 'That is a monarchy.'], ['Rule by the army generals', false, 'Democracy means the people decide.']], 'In Athens only free men could vote, but the idea spread across the world.'),
  mcq('y3.gr.sparta', 'y3-greece', 'What was Sparta famous for?', [['Its tough warriors', true], ['Its theatres and plays', false, 'Athens was more famous for theatre.'], ['Its huge stone pyramids', false, 'Pyramids were in Egypt.']], 'Spartan soldiers were some of the best-trained in Greece.'),
  mcq('y3.gr.trojan', 'y3-greece', 'In the legend of Troy, how did the Greeks get inside the city?', [['They hid inside a wooden horse', true], ['They dug a tunnel under the walls', false, 'The trick was a wooden horse.'], ['They flew over the walls', false, 'No flying in this legend!']], 'The Trojans pulled the horse inside as a prize. At night, the soldiers climbed out.'),
  fact('y3.gr.marathon', 'y3-greece', 'The marathon race is named after a battle in 490 BC. Who won the Battle of Marathon?', 'the Athenians', ['the Persians', 'the Romans', 'the Spartans'], 'A legend says a messenger ran all the way to Athens with the news. Today’s marathon is 26.2 miles.', C),
  fact('y3.gr.zeus', 'y3-greece', 'Who was the king of the Greek gods?', 'Zeus', ['Thor', 'Jupiter', 'Ra'], 'Zeus ruled from Mount Olympus and threw thunderbolts. (Jupiter was his Roman name.)', { accept: ['zeus'] }),
  fact('y3.gr.athena', 'y3-greece', 'The city of Athens was named after which goddess of wisdom?', 'Athena', ['Aphrodite', 'Hera', 'Freya'], 'Her great temple, the Parthenon, still stands on a hill called the Acropolis.', { accept: ['athene'] }),
  mcq('y3.gr.alphabet', 'y3-greece', 'The word “alphabet” comes from the first two Greek letters. What are they?', [['alpha and beta', true], ['A and B', false, 'Close, but in Greek they are called alpha and beta.'], ['alpha and omega', false, 'Omega is the LAST Greek letter.']], 'Alpha + beta = alphabet.'),
  mcq('y3.gr.hoplite', 'y3-greece', 'Greek foot soldiers, called hoplites, fought in a tight block with overlapping shields. What was it called?', [['a phalanx', true], ['a testudo', false, 'The testudo was the Roman tortoise.'], ['a longship', false, 'That was a Viking ship.']], 'Each soldier’s shield also helped protect the man beside him, so they had to stick together.'),
  mcq('y3.gr.theatre', 'y3-greece', 'What did the ancient Greeks give us that we still enjoy today?', [['Theatre', true], ['Television', false, 'Television was invented in 1926.'], ['Football', false, 'Modern football came from England much later.']], 'Greek actors wore masks and performed in huge open-air theatres.'),

  // --- earliest civilisations
  mcq('y3.civ.rivers', 'y3-civilisations', 'Why were the first cities built beside rivers?', [['For water, soil and travel', true], ['People liked the noise of rivers', false, 'It was about water, food and transport.'], ['Rivers kept away the Romans', false, 'The Romans came much later.']], 'Rivers flooded and left rich mud. Farmers grew extra food, so cities could grow.'),
  fact('y3.civ.cuneiform', 'y3-civilisations', 'About 5,200 years ago, people in Sumer invented one of the first kinds of writing, pressed into clay with a reed. What is it called?', 'cuneiform', ['hieroglyphs', 'runes', 'Latin'], 'Cuneiform means wedge-shaped, because of the shapes the reed made.', C),
  fact('y3.civ.mesopotamia', 'y3-civilisations', 'Sumer was in Mesopotamia, which means “the land between the rivers”. Which modern country is it in?', 'Iraq', ['Egypt', 'China', 'Greece'], 'The two rivers are the Tigris and the Euphrates.', { accept: ['iraq'] }),
  mcq('y3.civ.wheel', 'y3-civilisations', 'Which very important invention were the Sumerians among the first to use, about 5,500 years ago?', [['the wheel', true], ['the telephone', false, 'That was 1876!'], ['the aeroplane', false, 'That was 1903.']], 'First for making pots, then for carts.'),
  fact('y3.civ.indus', 'y3-civilisations', 'Which ancient civilisation built the cities of Mohenjo-daro and Harappa, with neat streets and drains?', 'the Indus Valley civilisation', ['the Romans in Italy', 'the Vikings of Norway', 'the Shang of China'], 'They lived about 4,500 years ago in what is now Pakistan and north-west India.', C),
  mcq('y3.civ.drains', 'y3-civilisations', 'What was amazing about Indus Valley cities?', [['They had planned streets and drains', true], ['They were built on the Moon', false, 'They were beside the River Indus.'], ['They had bright electric lights', false, 'Electricity came thousands of years later.']], 'Many houses had their own bathroom, connected to drains under the streets.'),
  order('y3.civ.order', 'y3-civilisations', 'Put these in order, earliest first.', ['Writing begins in Sumer', 'The Great Pyramid is built', 'The first Olympic Games', 'The Romans invade Britain'], 'About 3200 BC, about 2560 BC, 776 BC, AD 43.', ['about 3200 BC', 'about 2560 BC', '776 BC', 'AD 43']),
  mcq('y3.civ.surplus', 'y3-civilisations', 'Once farmers grew more food than they needed, what could other people do?', [['Do other jobs, like making pots', true], ['Stop eating food altogether', false, 'Everyone still needs food!'], ['Leave the city for ever', false, 'Extra food let cities grow.']], 'Spare food meant some people could become potters, builders, priests and scribes.'),
  fact('y3.civ.ziggurat', 'y3-civilisations', 'The Sumerians built huge stepped temples. What were they called?', 'ziggurats', ['pyramids', 'castles', 'igloos'], 'A ziggurat looks like a pyramid made of giant steps, with a temple at the top.', C),

  // --- castles under attack
  fact('y3.sg.trebuchet', 'y3-sieges', 'Which giant siege machine used a heavy counterweight to fling huge stones at castle walls?', 'a trebuchet', ['a battering ram', 'a drawbridge', 'a portcullis'], 'King Edward I had an enormous trebuchet called the “Warwolf” built to attack Stirling Castle in 1304.', C),
  fact('y3.sg.tower', 'y3-sieges', 'What did attackers push up to the castle walls so soldiers could climb across the top?', 'a siege tower', ['a trebuchet', 'a moat', 'a keep'], 'Siege towers were tall wooden towers on wheels, often covered in wet animal skins so they would not burn.', C),
  fact('y3.sg.ram', 'y3-sieges', 'What was used to smash down a castle gate?', 'a battering ram', ['a catapult', 'a crossbow', 'a portcullis'], 'Soldiers swung a huge tree trunk, often under a roof to protect them.', C),
  mcq('y3.sg.mine', 'y3-sieges', 'In 1215, how did King John’s army bring down a tower of Rochester Castle?', [['They dug a tunnel under it', true], ['They flew over it in a balloon', false, 'Balloons came hundreds of years later.'], ['They asked the guards nicely', false, 'It was a siege!']], 'When the props burned away, the tunnel collapsed and the tower fell in.'),
  mcq('y3.sg.concentric', 'y3-sieges', 'What is a concentric castle?', [['A castle with rings of walls', true], ['A castle made of concrete', false, 'Concentric means circles with the same centre.'], ['A castle with no walls at all', false, 'It has MORE walls, not fewer.']], 'If attackers got over the outer wall, they were trapped between two walls. Beaumaris in Wales is a famous example.'),
  fact('y3.sg.edward', 'y3-sieges', 'Which king built a ring of mighty castles in Wales, such as Conwy, Caernarfon, Harlech and Beaumaris?', 'Edward I', ['Henry VIII', 'Alfred', 'Charles III'], 'He built them after conquering Wales in the 1280s.', { accept: ['edward the first', 'edward 1', 'king edward i'] }),
  mcq('y3.sg.starve', 'y3-sieges', 'If attackers could not break in, what else could they do?', [['Wait until food ran out', true], ['Give up and go home at once', false, 'Sometimes they did, but often they waited.'], ['Ring the castle doorbell', false, 'Castles did not have doorbells!']], 'A siege could last for months. Castles had wells and food stores to hold out.'),
  fact('y3.sg.murder', 'y3-sieges', 'Defenders could drop stones through holes in the ceiling of the gateway. What were these holes called?', 'murder holes', ['arrow slits', 'battlements', 'windows'], 'Attackers who got through the gate were still not safe.', C),
  fact('y3.sg.slit', 'y3-sieges', 'Narrow openings in castle walls let archers shoot out but were hard to hit from outside. What were they called?', 'arrow slits', ['murder holes', 'chimneys', 'drains'], 'They were wide on the inside and very narrow on the outside.', C),

  // --- Battle of Britain
  fact('y3.bb.year', 'y3-britain1940', 'In which year was the Battle of Britain fought?', '1940', ['1914', '1945', '1066'], 'It lasted from July to October 1940.'),
  mcq('y3.bb.what', 'y3-britain1940', 'What was the Battle of Britain?', [['A battle in the skies', true], ['A big battle at sea', false, 'It was fought in the air.'], ['A battle between knights', false, 'It was in 1940, with aeroplanes.']], 'Germany wanted to control the skies before trying to invade. The RAF stopped them.'),
  mcq('y3.bb.radar', 'y3-britain1940', 'How did radar help the RAF?', [['It spotted enemy planes far away', true], ['It made the planes invisible', false, 'Radar finds planes; it does not hide them.'], ['It fired the planes’ guns', false, 'Radar is for seeing far away.']], 'A chain of radar stations along the coast, called Chain Home, sent out radio waves that bounced back off planes.'),
  fact('y3.bb.observer', 'y3-britain1940', 'Radar could not see planes once they had crossed the coast. Who tracked them over land, with binoculars?', 'the Observer Corps', ['the Home Guard', 'the Land Girls', 'the Navy'], 'Thousands of volunteers watched the skies from posts all over the country.', C),
  mcq('y3.bb.hurricane', 'y3-britain1940', 'The Spitfire is the most famous fighter. Which other RAF fighter shot down even more enemy planes in the battle?', [['the Hurricane', true], ['the Concorde', false, 'Concorde was a passenger jet, first flown in 1969.'], ['the Wright Flyer', false, 'That was the first aeroplane, in 1903.']], 'There were more Hurricanes than Spitfires in 1940, and they were tough and steady.'),
  mcq('y3.bb.few', 'y3-britain1940', 'Winston Churchill said, “Never was so much owed by so many to so few.” Who were “the Few”?', [['The RAF fighter pilots', true], ['The king and queen', false, 'He meant the pilots.'], ['The German pilots', false, 'He was thanking the RAF pilots.']], 'There were only about 3,000 RAF aircrew in the battle, protecting millions of people.'),
  mcq('y3.bb.countries', 'y3-britain1940', 'Where did the RAF pilots in the Battle of Britain come from?', [['Britain and many other countries', true], ['Only from London', false, 'Pilots came from all over the world.'], ['Only from the USA', false, 'There were a few Americans, but pilots came from many countries.']], 'The Polish 303 Squadron was one of the most successful of all.'),
  mcq('y3.bb.plotters', 'y3-britain1940', 'In the operations rooms, what did members of the Women’s Auxiliary Air Force (WAAF) do?', [['Tracked planes on big map tables', true], ['Flew the fighter planes in battle', false, 'Women did not fly in combat in 1940, but some flew planes between airfields.'], ['Cooked all the meals for pilots', false, 'Their job was tracking the battle.']], 'Commanders looked down at the table and decided which squadrons to send.'),
  fact('y3.bb.dowding', 'y3-britain1940', 'Who was in charge of RAF Fighter Command and built its warning and control system?', 'Hugh Dowding', ['Winston Churchill', 'Alan Turing', 'Neil Armstrong'], 'His system joined radar, observers, map rooms and squadrons together.', C),
  fact('y3.bb.day', 'y3-britain1940', 'Which day is remembered as Battle of Britain Day?', '15 September', ['5 November', '11 November', '25 December'], 'On 15 September 1940 the RAF beat off two huge attacks. Soon afterwards the invasion plan was put off.', C),

  // --- Home Front
  mcq('y3.hf.blitz', 'y3-homefront', 'What was the Blitz?', [['The bombing of British cities', true], ['A famous football match', false, 'It was the bombing of cities.'], ['A type of fighter plane', false, 'It was a long period of air raids.']], 'Blitz is short for the German word “Blitzkrieg”, meaning lightning war. London was bombed for 57 nights in a row.'),
  fact('y3.hf.anderson', 'y3-homefront', 'Which air-raid shelter was half-buried in the garden and made of curved steel sheets?', 'an Anderson shelter', ['a Morrison shelter', 'a castle', 'a bunker on the Moon'], 'Families covered them with earth, and some grew vegetables on top!', C),
  fact('y3.hf.morrison', 'y3-homefront', 'Which shelter was a strong steel cage that went indoors and could be used as a table?', 'a Morrison shelter', ['an Anderson shelter', 'a tube station', 'a tent'], 'Families crawled inside it during a raid.', C),
  mcq('y3.hf.underground', 'y3-homefront', 'Where did many Londoners shelter during air raids?', [['In Underground stations', true], ['On the roofs', false, 'Roofs were the most dangerous place!'], ['In the River Thames', false, 'They went underground.']], 'Thousands of people slept on the platforms of the Tube.'),
  mcq('y3.hf.blackout', 'y3-homefront', 'Why did everyone have to keep a “blackout” at night?', [['So bombers could not see the towns', true], ['To save money on electricity', false, 'The main reason was to hide towns from bombers.'], ['So children would go to sleep', false, 'Nice idea, but it was to hide from bombers.']], 'Thick curtains covered every window, and street lights were turned off. Wardens shouted, “Put that light out!”'),
  fact('y3.hf.landgirls', 'y3-homefront', 'Women who did farm work during the war were part of the Women’s Land Army. What were they nicknamed?', 'Land Girls', ['Spitfire Girls', 'Wrens', 'the Few'], 'They ploughed fields, milked cows and drove tractors, so Britain had enough food.', C),
  mcq('y3.hf.dig', 'y3-homefront', 'What did the “Dig for Victory” campaign ask people to do?', [['Grow their own vegetables', true], ['Dig tunnels all the way to Germany', false, 'It was about growing food at home.'], ['Dig for buried pirate treasure', false, 'It was about vegetables!']], 'Ships bringing food were being attacked, so growing your own helped everyone.'),
  fact('y3.hf.gasmask', 'y3-homefront', 'What did every child carry in a cardboard box, just in case?', 'a gas mask', ['a sandwich', 'a toy', 'a torch'], 'Luckily, gas was never used on Britain’s towns.', C),
  fact('y3.hf.homeguard', 'y3-homefront', 'Men who were too old or young to join the army, or did vital jobs, could volunteer to defend their town. What was this group called?', 'the Home Guard', ['the Observer Corps', 'the Land Army', 'the Roman legion'], 'The TV comedy “Dad’s Army” is about the Home Guard.', C),
  mcq('y3.hf.ration', 'y3-homefront', 'Why was food rationed during the war?', [['So everyone got a fair share', true], ['People wanted to lose weight', false, 'It was about fair shares when food was scarce.'], ['All the shops were closed', false, 'Shops were open, but food was limited.']], 'Rationing began in January 1940. Everyone had a ration book.'),
  fact('y3.hf.ve', 'y3-homefront', 'People had street parties when the war in Europe ended. What was that day called?', 'VE Day', ['D-Day', 'Boxing Day', 'Remembrance Day'], 'VE means Victory in Europe. It was 8 May 1945.', { accept: ['victory in europe day', 've'] }),

  // --- historical skills
  mcq('y3.sk.bc', 'y3-skills', 'Which happened earlier: 500 BC or 200 BC?', [['500 BC', true], ['200 BC', false, 'BC years count DOWN towards AD 1, so 500 BC is further back in time.'], ['They are the same time', false, 'They are 300 years apart.']], 'BC years count backwards: the bigger the number, the longer ago.'),
  mcq('y3.sk.ad', 'y3-skills', 'What does AD stand for?', [['Anno Domini', true], ['After Dinosaurs', false, 'Ha! It is Latin: Anno Domini, “in the year of the Lord”.'], ['Ancient Days', false, 'It is Latin: Anno Domini.']], 'AD years count up from the year Christians believed Jesus was born. Some people write CE and BCE instead.'),
  fact('y3.sk.century', 'y3-skills', 'How many years are in a century?', '100', ['10', '1000', '50'], 'Cent means a hundred, like a centipede with (supposedly) 100 legs.'),
  fact('y3.sk.decade', 'y3-skills', 'How many years are in a decade?', '10', ['100', '12', '1000'], 'Dec means ten.'),
  mcq('y3.sk.primary', 'y3-skills', 'Which of these is a PRIMARY source about the Romans?', [['A Roman soldier’s letter', true], ['A history book written last year', false, 'That was made long afterwards: a secondary source.'], ['A new film about gladiators', false, 'Films are made much later: secondary sources.']], 'A primary source comes from the time itself. A secondary source is made later by someone studying the past.'),
  mcq('y3.sk.secondary', 'y3-skills', 'Which of these is a SECONDARY source about the Vikings?', [['A modern book about Viking life', true], ['A Viking sword found in a river', false, 'That object comes from the time: a primary source.'], ['Runes carved by a Viking', false, 'They were carved at the time: primary.']], 'Secondary sources are useful too, because historians bring lots of evidence together.'),
  fact('y3.sk.archaeologist', 'y3-skills', 'Who digs carefully in the ground to find things from the past?', 'an archaeologist', ['an astronaut', 'a vet', 'a pharaoh'], 'Archaeologists use trowels and brushes and record exactly where everything is found.', C),
  fact('y3.sk.artefact', 'y3-skills', 'An object made by people in the past, like a coin or a pot, is called an…', 'artefact', ['ancestor', 'anagram', 'antelope'], 'Artefacts are clues to how people lived.', { accept: ['artifact', 'an artefact'] }),
  mcq('y3.sk.1066', 'y3-skills', 'In which century was 1066?', [['the 11th century', true], ['the 10th century', false, 'The 1000s are the 11th century, just as the 1900s were the 20th century.'], ['the 16th century', false, 'The 1500s were the 16th century.']], 'Years 1001 to 1100 make the 11th century. The century number is one more than the hundreds.'),
  mcq('y3.sk.zero', 'y3-skills', 'Which year came straight after 1 BC?', [['AD 1', true], ['year 0', false, 'There was no year 0! It goes 1 BC, then AD 1.'], ['2 BC', false, '2 BC came BEFORE 1 BC.']], 'The calendar jumps from 1 BC to AD 1.'),

  // --- Normans (stretch)
  fact('y3.no.domesday', 'y3-normans', 'In 1086, William the Conqueror sent people all over England to record who owned what land and animals. What is this record called?', 'the Domesday Book', ['the Bayeux Tapestry', 'the Magna Carta', 'the Doomsday Diary'], 'It still exists and you can look up almost any old village in it.', C),
  mcq('y3.no.motte', 'y3-normans', 'What was a motte and bailey castle?', [['A wooden tower on a mound', true], ['A castle made of ice', false, 'They were earth and wood at first.'], ['A kind of Norman ship', false, 'It was a castle.']], 'They could be built in a few weeks. Later many were rebuilt in stone.'),
  order('y3.no.feudal', 'y3-normans', 'Put the feudal system in order, from most powerful to least.', ['the king', 'barons', 'knights', 'peasants'], 'The king gave land to barons, barons gave land to knights, and peasants worked the land.'),
  fact('y3.no.tower', 'y3-normans', 'Which great stone tower did William build in London?', 'the White Tower', ['Big Ben', 'the Shard', 'Nelson’s Column'], 'The White Tower is the heart of the Tower of London. It was built to show Londoners who was in charge.', C),
  mcq('y3.no.french', 'y3-normans', 'The Normans spoke French. Which English words come from Norman French?', [['beef and pork', true], ['cow and pig', false, 'Those are older English words. Peasants raised cows and pigs; the Normans ate “boeuf” and “porc”.'], ['cat and dog', false, 'Those are Old English words.']], 'English took thousands of words from Norman French.'),
  mcq('y3.no.why', 'y3-normans', 'Why did William want the Domesday Book made?', [['To collect taxes', true], ['To write down bedtime stories', false, 'It is a record of land and animals.'], ['To plan a royal holiday', false, 'It was about land and taxes.']], 'People said it was like Judgement Day (“Doomsday”): there was no escaping it!'),
  mcq('y3.no.stone', 'y3-normans', 'Why did the Normans later rebuild many wooden castles in stone?', [['Stone could not burn', true], ['Wood was far too expensive', false, 'Stone was actually more work. It was about strength and fire.'], ['Stone castles were warmer', false, 'Stone castles were cold! It was about strength.']], 'A wooden tower could be set on fire by attackers.'),
  mcq('y3.no.villein', 'y3-normans', 'What did most peasants (villeins) have to do?', [['Work on their lord’s land', true], ['Fight in jousting tournaments', false, 'That was for knights.'], ['Nothing at all, all day', false, 'They worked very hard.']], 'They could not leave the village without the lord’s permission.'),

  // --- Shang China (stretch)
  fact('y3.shang.when', 'y3-shang', 'About how long ago did the Shang dynasty begin in China?', 'about 3,600 years ago', ['about 360 years ago', 'about 36 years ago', 'about 36,000 years ago'], 'The Shang ruled from about 1600 BC to about 1046 BC.', C),
  fact('y3.shang.river', 'y3-shang', 'Which river did the Shang live beside?', 'the Yellow River', ['the Nile', 'the Thames', 'the Indus'], 'Its mud is yellow, which gives the river its name.', C),
  mcq('y3.shang.oracle', 'y3-shang', 'What were oracle bones?', [['Bones used to ask the ancestors', true], ['Fossils of dinosaurs', false, 'They were animal bones used to ask questions.'], ['Musical instruments for feasts', false, 'They were used to ask the ancestors questions.']], 'They are the oldest Chinese writing we have, and many Chinese characters come from them.'),
  mcq('y3.shang.bronze', 'y3-shang', 'What were the Shang especially skilled at making?', [['Bronze vessels and weapons', true], ['Steam engines and trains', false, 'Those came about 3,000 years later.'], ['Plastic toys and games', false, 'Plastic is very modern.']], 'Their bronze pots were used in ceremonies for the ancestors.'),
  mcq('y3.shang.writing', 'y3-shang', 'Why are oracle bones so important to historians today?', [['They have the oldest Chinese writing', true], ['They show what dinosaurs ate', false, 'They are from people, not dinosaurs.'], ['They were used as money', false, 'They were for asking questions, and now they are evidence.']], 'They tell us about Shang kings, battles, weather and harvests.'),
  fact('y3.shang.fuhao', 'y3-shang', 'Which Shang queen was also a general who led armies? Her tomb was found in 1976.', 'Fu Hao', ['Boudica', 'Cleopatra', 'Elizabeth I'], 'Her tomb was full of bronze, jade and weapons.', C),
];

// the one timeline for the course: Year 2’s, with Year 3 periods split out and new events added
const PERIODS_Y3 = [['Stone Age', -3500, -2500], ['Bronze Age', -2500, -800], ['Iron Age', -800, 43]];
const EVENTS_Y3 = [
  [-3200, 'Writing begins in Sumer', ['history.y3.civ.cuneiform']],
  [-2300, 'The Amesbury Archer', ['history.y3.sa.amesbury']],
  [-1600, 'Shang China begins', ['history.y3.shang.when']],
  [-800, 'Iron Age begins in Britain', ['history.y3.ia.when']],
  [-776, 'First Olympic Games', ['history.y3.gr.olympics']],
  [-490, 'Battle of Marathon', ['history.y3.gr.marathon']],
  [-55, 'Julius Caesar visits Britain', ['history.y3.leg.caesar']],
  [61, 'Boudica’s revolt', ['history.y3.bo.when', 'history.y3.bo.towns']],
  [410, 'The Romans leave Britain', ['history.y3.rl.leave']],
  [597, 'Augustine arrives in Kent', ['history.y3.sx.augustine']],
  [878, 'Alfred defeats Guthrum', ['history.y3.vk.edington']],
  [927, 'Athelstan, first king of England', ['history.y3.vk.athelstan']],
  [1016, 'Cnut becomes king', ['history.y3.vk.cnut']],
  [1086, 'The Domesday Book', ['history.y3.no.domesday']],
];
const base = KS1_HISTORY.find((d) => d.timeline).timeline;
const timeline = {
  periods: [...base.periods.filter((p) => p.from >= 43), ...PERIODS_Y3.map(([name, from, to]) => ({ name, from, to }))].sort((a, b) => a.from - b.from),
  events: [...base.events, ...EVENTS_Y3.map(([year, label, ids]) => ({ year, label, items: ids }))].sort((a, b) => a.year - b.year),
};

export default [
  { subject: 'history', deck: 'y3', topics, items },
  { subject: 'history', deck: 'y3-timeline', topics: [], items: [], timeline },
];
